import { MAPS_TO_TARGETS, previewMapping } from "./connectorMapping";

type Incident = { id:string; incident_number:string; title:string; description:string; severity:string; status:string; source:string; service:string; dedup_key:string; assignee?:string|null; created_at:string; updated_at:string };
type Policy = { id:string; name:string; description:string; timezone:string; repeat_count:number; repeat_every_minutes:number; steps:{delay_minutes:number;target_type:string;target:string}[] };
type NotifyUser = { handle:string; team:string; groups:string[]; channels:Record<string,{destination:string;active:boolean}> };
type EventRow = { id:number; kind:string; actor:string; note:string; created_at:string };
type ApiKey = { id:string; name:string; role:string; active:boolean; last_used_at?:string|null; expires_at?:string|null };
type Delivery = { id:string; channel:string; status:string; attempts:number; next_attempt_at:string; last_error:string };
