  const [refreshing,setRefreshing]=useState(false); const [lastUpdated,setLastUpdated]=useState(""); const refreshLock=useRef(false);
  const [rows,setRows]=useState<Incident[]>([]); const [totalIncidents,setTotalIncidents]=useState(0); const [matchingIncidents,setMatchingIncidents]=useState(0); const [selected,setSelected]=useState<Incident|null>(null); const [events,setEvents]=useState<EventRow[]>([]); const [policies,setPolicies]=useState<Policy[]>([]);
  const [navPosition,setNavPosition]=useState<"left"|"right"|"top"|"bottom">("left"); const [navActive,setNavActive]=useState("incidents");
