  const [page,setPage]=useState<"incidents"|"users"|"policies"|"schedules"|"deliveries"|"integrations"|"tenants"|"analysis"|"account">("incidents"); const [users,setUsers]=useState<NotifyUser[]>([]); const [deliveries,setDeliveries]=useState<Delivery[]>([]); const [schedules,setSchedules]=useState<OnCallSchedule[]>([]); const [scheduleName,setScheduleName]=useState(""); const [scheduleTimezone,setScheduleTimezone]=useState("UTC"); const [scheduleInterval,setScheduleInterval]=useState(480); const [scheduleStartsAt,setScheduleStartsAt]=useState(localDateTime(new Date().toISOString())); const [scheduleMembers,setScheduleMembers]=useState<string[]>([]); const [editingScheduleId,setEditingScheduleId]=useState<string|null>(null); const [tenants,setTenants]=useState<TenantRecord[]>([]); const [tenantSecret,setTenantSecret]=useState(""); const [tenantMenu,setTenantMenu]=useState<TenantMenu|null>(null); const [managedTenant,setManagedTenant]=useState<TenantRecord|null>(null); const [managedTenantKeys,setManagedTenantKeys]=useState<ApiKey[]>([]); const [managedTenantSecret,setManagedTenantSecret]=useState(""); const [managedExpiryDrafts,setManagedExpiryDrafts]=useState<Record<string,string>>({}); const [incidentMenu,setIncidentMenu]=useState<IncidentMenu|null>(null); const [userModal,setUserModal]=useState(false); const [editingUser,setEditingUser]=useState<NotifyUser|null>(null); const [navGroupsClosed,setNavGroupsClosed]=useState<string[]>([]); const [scheduleTeam,setScheduleTeam]=useState(""); const [myResp,setMyResp]=useState<MyResponder|null>(null); const [responders,setResponders]=useState<Responder[]>([]); const [leads,setLeads]=useState<TeamLead[]>([]); const [assignRequests,setAssignRequests]=useState<AssignRequest[]>([]); const [spikes,setSpikes]=useState<SpikeRow[]>([]); const [assignTarget,setAssignTarget]=useState<Incident|null>(null); const [assignChoice,setAssignChoice]=useState(""); const [resolveTarget,setResolveTarget]=useState<Incident|null>(null); const [spikeTarget,setSpikeTarget]=useState<Incident|null>(null); const [spikeAnswer,setSpikeAnswer]=useState<SpikeRow|null>(null); const [selectedGroups,setSelectedGroups]=useState<string[]>([]); const [groupDraftName,setGroupDraftName]=useState(""); const [policyModal,setPolicyModal]=useState(false); const [draftSteps,setDraftSteps]=useState([{delay_minutes:0,target_type:"team",target:""}]);
  const [keys,setKeys]=useState<ApiKey[]>([]); const [newKeyExpiry,setNewKeyExpiry]=useState(""); const [keyExpiryDrafts,setKeyExpiryDrafts]=useState<Record<string,string>>({}); const [query,setQuery]=useState(""); const [queryInput,setQueryInput]=useState(""); const [status,setStatus]=useState("open"); const [severity,setSeverity]=useState("all");
  const [modal,setModal]=useState<"incident"|"test"|null>(null); const [settings,setSettings]=useState(false); const [access,setAccess]=useState(false); const [busy,setBusy]=useState(false); const [toast,setToast]=useState(""); const [secret,setSecret]=useState(""); const [newKeyName,setNewKeyName]=useState(""); const [newKeyRole,setNewKeyRole]=useState("integration");
  const request=useCallback(async(path:string,opts:RequestInit={},credential=key)=>{const headers=new Headers(opts.headers);if(credential)headers.set("Authorization",`Bearer ${credential}`);else headers.delete("Authorization");headers.set("Content-Type","application/json");const res=await fetch(`/backend${path}`,{...opts,headers,credentials:"same-origin"});if(!res.ok){if(res.status===401){setCurrentUser(null);setLoginRequired(true)}let message=`Request failed (${res.status})`;try{message=(await res.json()).error||message}catch{}throw new Error(message)}return res.status===204?null:res.json()},[key]);
  const ping=(s:string)=>{setToast(s);window.setTimeout(()=>setToast(""),3000)};
  const refresh=useCallback(async()=>{if(refreshLock.current)return;refreshLock.current=true;setRefreshing(true);try{if(!key){const me=await request("/v1/auth/me",{cache:"no-store"});setCurrentUser(me.user);setRole(me.user.role);setTenant(`${me.tenant.name} · ${me.tenant.slug}`);setLoginRequired(false)}const incidentPath=query.trim()?`/v1/incidents?search=${encodeURIComponent(query.trim())}`:"/v1/incidents";const inc=await request(incidentPath,{cache:"no-store"});setRows(inc.incidents||[]);setTotalIncidents(inc.total_incidents??(inc.incidents||[]).length);setMatchingIncidents(inc.matching_incidents??(inc.incidents||[]).length);setLastUpdated(new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit",second:"2-digit"}));const [who,pol]=await Promise.allSettled([request("/v1/tenant",{cache:"no-store"}),request("/v1/escalation-policies",{cache:"no-store"})]);if(who.status==="fulfilled"){setRole(who.value.role);setProductOwner(!!who.value.is_product_owner);setTenant(`${who.value.tenant.name} · ${who.value.tenant.slug}`)}if(pol.status==="fulfilled")setPolicies(pol.value.policies||[]);const wfRole=who.status==="fulfilled"?who.value.role:"";if(["owner","admin","responder"].includes(wfRole)){const [m,r,q,sp]=await Promise.allSettled([request("/v1/me/responder",{cache:"no-store"}),request("/v1/responders",{cache:"no-store"}),request("/v1/assignment-requests",{cache:"no-store"}),request("/v1/spikes",{cache:"no-store"})]);if(m.status==="fulfilled")setMyResp(m.value);if(r.status==="fulfilled"){setResponders(r.value.responders||[]);setLeads(r.value.leads||[])}if(q.status==="fulfilled")setAssignRequests(q.value.requests||[]);if(sp.status==="fulfilled")setSpikes(sp.value.spikes||[])}}catch(e){if(!key){setLoginRequired(true)}else ping(`Could not refresh relays: ${(e as Error).message}`)}finally{refreshLock.current=false;setRefreshing(false)}},[key,query,request]);
