  const saveManagedExpiration=async(id:string)=>{if(!managedTenant)return;try{const draft=managedExpiryDrafts[id]??"";const r=await request(`/v1/tenants/${managedTenant.id}/api-keys/${id}`,{method:"PUT",body:JSON.stringify({expires_at:draft?new Date(draft).toISOString():null})});setManagedTenantKeys(managedTenantKeys.map(k=>k.id===id?r.api_key:k));ping(draft?"Tenant API key expiration updated":"Tenant API key expiration removed")}catch(e){ping((e as Error).message)}};
