  const authModeForm=loginMode==="recover"?<form className="auth-form" onSubmit={submitRecovery}><p>Reset an existing tenant login with its owner API key. Active sessions for that account will be revoked.</p><label className="field">Tenant owner API key<input required type="password" value={bootstrapKey} onChange={e=>setBootstrapKey(e.target.value)} autoComplete="off"/></label><label className="field">Account email<input required type="email" value={loginEmail} onChange={e=>setLoginEmail(e.target.value)} autoComplete="username"/></label><label className="field">New password (12 characters minimum)<input required type="password" minLength={12} maxLength={1024} value={loginPassword} onChange={e=>setLoginPassword(e.target.value)} autoComplete="new-password"/></label>{authError&&<div className="warning">{authError}</div>}<button className="btn primary" disabled={authBusy}>{authBusy?"Resetting…":"Reset password"}</button></form>:loginMode==="login"?<form className="auth-form" onSubmit={submitLogin}><label className="field">Tenant slug<input required value={loginTenant} onChange={e=>setLoginTenant(e.target.value)} placeholder="acme" autoComplete="organization"/></label><label className="field">Email<input required type="email" value={loginEmail} onChange={e=>setLoginEmail(e.target.value)} autoComplete="username"/></label><label className="field">Password<input required type="password" value={loginPassword} onChange={e=>setLoginPassword(e.target.value)} autoComplete="current-password"/></label>{authError&&<div className="warning">{authError}</div>}<button className="btn primary" disabled={authBusy}>{authBusy?"Signing in…":"Sign in"}</button></form>:<form className="auth-form" onSubmit={submitSetup}><p>Create the tenant’s first owner login. The tenant API key is used once to authorize setup and is not saved.</p><label className="field">Tenant API key<input required type="password" value={bootstrapKey} onChange={e=>setBootstrapKey(e.target.value)} autoComplete="off"/></label><label className="field">Display name<input required maxLength={120} value={loginName} onChange={e=>setLoginName(e.target.value)}/></label><label className="field">Email<input required type="email" value={loginEmail} onChange={e=>setLoginEmail(e.target.value)} autoComplete="username"/></label><label className="field">Password (12 characters minimum)<input required type="password" minLength={12} maxLength={1024} value={loginPassword} onChange={e=>setLoginPassword(e.target.value)} autoComplete="new-password"/></label>{authError&&<div className="warning">{authError}</div>}<button className="btn primary" disabled={authBusy}>{authBusy?"Creating account…":"Create owner login"}</button></form>;  if(!authReady)return <div className="auth-screen"><section className="auth-card"><div className="logo">R</div><h1>RelayOps</h1><p>Checking your sign-in session…</p></section></div>;
  if(loginRequired)return <div className="auth-screen"><section className="auth-card"><div className="logo">R</div><h1>RelayOps</h1><p>Sign in to your tenant workspace.</p><div className="auth-tabs"><button type="button" className={loginMode==="login"?"selected":""} onClick={()=>{setLoginMode("login");setAuthError("")}}>Sign in</button><button type="button" className={loginMode==="setup"?"selected":""} onClick={()=>{setLoginMode("setup");setAuthError("")}}>First-time setup</button><button type="button" className={loginMode==="recover"?"selected":""} onClick={()=>{setLoginMode("recover");setAuthError("")}}>Recover access</button></div>{authModeForm}</section></div>;  const active=rows.filter(x=>x.status!=="resolved"),critical=active.filter(x=>x.severity==="critical").length,acked=active.filter(x=>x.status==="acknowledged").length,resolved=rows.filter(x=>x.status==="resolved"&&new Date(x.updated_at).toDateString()===new Date().toDateString()).length;
